mapper.select:
SELECT lt.id AS bindId, lt.user_id AS userId, lt.room_id AS roomId, lt.seat_id AS seatId, IFNULL(t.checkInDays, 0) AS checkInDays, IFNULL(t.checkOutDays, 0) AS checkOutDays, IFNULL(t.bothDays, 0) AS bothDays FROM long_term_seat lt LEFT JOIN ( SELECT sr.user_id, COUNT(DISTINCT CASE WHEN sr.check_in_time IS NOT NULL THEN sr.reserve_date END) AS checkInDays, COUNT(DISTINCT CASE WHEN sr.check_out_time IS NOT NULL THEN sr.reserve_date END) AS checkOutDays, COUNT(DISTINCT CASE WHEN sr.check_in_time IS NOT NULL AND sr.check_out_time IS NOT NULL THEN sr.reserve_date END) AS bothDays FROM seat_reservation sr WHERE sr.reserve_date BETWEEN #{startDate} AND #{endDate} AND sr.room_id = #{roomId} GROUP BY sr.user_id ) t ON t.user_id = lt.user_id WHERE lt.status = 'ACTIVE'
AND lt.room_id = #{roomId}
ORDER BY lt.id
